// Venue notice PRODUCER (Round 17, Eddie 2026-11-17) — headless.
//
// Until Round 17 this file rendered the venue pill itself (a
// compact top-centre card). Eddie's notifications brief replaced
// the pills with one system — a store, corner toasts, and a
// permanent home — so this component no longer renders anything:
// it keeps its old job of deciding WHEN a venue notice is news and
// writes that news into the notifications store
// (utils/notifications.ts), where NotificationToasts pops it at the
// corner and /notifications keeps it. One system, no parallel
// pill: a notice can never show twice in two shapes.
//
// Everything about the old discipline is preserved:
// - Trigger discipline: the first notice surfaces shortly after
//   the app opens; each next one only after a check-in or a move
//   to a new page — never on a timer blast, one per trigger.
// - INVITES are personal: Quiet (Just here) / Battle-only /
//   Invisible presence suppresses them. Promos and events are
//   venue broadcasts and don't need presence.
// - Per-day dismissal (data/venueBuzz.ts) still retires a notice
//   for the day — now via the toast's ✕ or the producer's own
//   eligibility read. The store's per-day record id dedupes too,
//   so a notice is recorded (and toasted) at most once a day.
// - Tapping through lands on that venue on the World Map (the
//   store record carries the venue id; activate() stashes the
//   venue-focus handoff, exactly as the pill's "View map" did).
// Demo venues only, demo-framed on the record.
import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { DEMO_VENUES } from '../data/venues';
import { allVenueNotices, loadVenueNoticeDismissals, type VenueNotice } from '../data/venueBuzz';
import { useNotifications } from '../contexts/NotificationsContext';
import { usePresence } from '../contexts/PresenceContext';
import { useVenue } from '../contexts/VenueContext';
import { localDateString } from '../utils/presence';

const KIND_EMOJI: Record<VenueNotice['kind'], string> = {
  event: '🎉',
  promo: '📣',
  invite: '💌',
};

const VenueNotification: React.FC = () => {
  const location = useLocation();
  const { notify } = useNotifications();
  const { networkingStatus, visibility } = usePresence();
  const { checkedInVenueId } = useVenue();
  const [shownCount, setShownCount] = useState(0);
  const [armed, setArmed] = useState(false);
  const triggerRef = useRef<string>('');

  // Invites are personal — they respect presence. Promos/events are
  // venue broadcasts.
  const invitesAllowed = networkingStatus === 'open' && visibility !== 'invisible';

  // Read dismissals fresh each render: the toast's ✕ writes them
  // outside this component, and the next trigger must honor them.
  const dismissed = loadVenueNoticeDismissals();
  const eligible = allVenueNotices().filter(
    n => !dismissed.some(d => d.id === n.id) && (n.kind !== 'invite' || invitesAllowed)
  );

  // Trigger discipline: the first notice arms ~2.5s after the app
  // opens; after that, a notice only becomes showable when the
  // trigger changes — a check-in or a page move. shownCount is how
  // many have been presented under the current trigger.
  const trigger = `${location.pathname}|${checkedInVenueId ?? 'none'}`;
  useEffect(() => {
    if (triggerRef.current !== trigger) {
      triggerRef.current = trigger;
      setShownCount(0);
      setArmed(false);
      const t = window.setTimeout(() => setArmed(true), 1200);
      return () => window.clearTimeout(t);
    }
    return undefined;
  }, [trigger]);
  useEffect(() => {
    const t = window.setTimeout(() => setArmed(true), 2500);
    return () => window.clearTimeout(t);
  }, []);

  const current: VenueNotice | null = armed && shownCount < 1 ? (eligible[0] ?? null) : null;

  useEffect(() => {
    if (!current) return;
    const venue = DEMO_VENUES.find(v => v.id === current.venueId);
    if (!venue) return;
    const headline =
      current.kind === 'invite'
        ? `${venue.name} invites you`
        : current.kind === 'event'
          ? `${current.headline} at ${venue.name}`
          : `${venue.name} — ${current.headline}`;
    notify({
      // Per-day id: the store dedupes on it, so this notice is
      // recorded (and toasted) at most once per local day.
      id: `venue-${current.id}-${localDateString()}`,
      kind: 'venue',
      title: `${KIND_EMOJI[current.kind]} ${headline}`,
      body: current.body,
      route: '/map',
      venueId: current.venueId,
      sourceId: current.id,
      demo: true,
    });
    setShownCount(c => c + 1);
  }, [current, notify]);

  return null;
};

export default VenueNotification;
