// Auth state for the multiplayer (Phase 1) features. Wraps the Supabase
// client from src/utils/supabaseClient.ts. Signed-out play is untouched:
// nothing here redirects or walls anything off — the game works exactly
// as before without a session, and this provider only adds auth where a
// page (Profile) asks for it.
import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import type { User } from '@supabase/supabase-js';
import { supabase } from '../utils/supabaseClient';
import { appUrl } from '../utils/appUrl';
import { mergeLocalProfileWithAccount } from '../utils/accountMerge';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  // The last sign-in/up error, as a short message for the UI. Null when
  // the last auth action succeeded (or none ran yet).
  authError: string | null;
  // A non-error status line, e.g. the "check your email" note after a
  // sign-up that needs confirmation. Null when there is nothing to say.
  authNotice: string | null;
  signUp: (email: string, password: string) => Promise<void>;
  signIn: (email: string, password: string) => Promise<void>;
  signInWithGoogle: () => Promise<void>;
  signOut: () => Promise<void>;
  // Password reset: sends the reset email for the given address.
  // Reports through authError / authNotice like the other actions.
  resetPassword: (email: string) => Promise<void>;
  // True when the app was opened from a password-reset email link
  // (Supabase PASSWORD_RECOVERY event / recovery params in the URL).
  // The recovery form shows while this is set; the recovery session
  // underneath is already a signed-in session.
  recoveryMode: boolean;
  // Sets the new password on the current (recovery) session.
  // Resolves to an error message, or null on success.
  updatePassword: (password: string) => Promise<string | null>;
  // Closes the recovery form without changing the password.
  dismissRecovery: () => void;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  loading: true,
  authError: null,
  authNotice: null,
  signUp: async () => {},
  signIn: async () => {},
  signInWithGoogle: async () => {},
  signOut: async () => {},
  resetPassword: async () => {},
  recoveryMode: false,
  updatePassword: async () => null,
  dismissRecovery: () => {},
});

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [authError, setAuthError] = useState<string | null>(null);
  const [authNotice, setAuthNotice] = useState<string | null>(null);
  // PASSWORD RECOVERY: set when this app load came from a reset
  // email link. supabase-js consumes the recovery params from the
  // URL, opens a session, and fires PASSWORD_RECOVERY; the hash
  // check covers the first paint before that event lands.
  const [recoveryMode, setRecoveryMode] = useState<boolean>(() => {
    try {
      return window.location.hash.includes('type=recovery');
    } catch {
      return false;
    }
  });
  // LOCAL → ACCOUNT MERGE (Step 4): when a session appears, the
  // device display name and the account's profiles row are merged
  // exactly once per account per app load (see accountMerge.ts).
  // Signing in never deletes or resets any on-device game data —
  // the merge only ADDS the local name to a nameless account row,
  // or adopts the account name onto the device.
  const mergedForRef = useRef<string | null>(null);
  const mergeOnSession = useCallback((nextUser: User | null) => {
    if (!nextUser) return;
    if (mergedForRef.current === nextUser.id) return;
    mergedForRef.current = nextUser.id;
    void mergeLocalProfileWithAccount(nextUser.id);
  }, []);

  useEffect(() => {
    let mounted = true;
    supabase.auth
      .getSession()
      .then(({ data }) => {
        if (mounted) {
          setUser(data.session?.user ?? null);
          mergeOnSession(data.session?.user ?? null);
        }
      })
      .catch(() => {
        // No session (or the client is offline) — signed-out play stays
        // available; the UI shows the sign-in form, never a crash.
        if (mounted) setUser(null);
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'PASSWORD_RECOVERY') setRecoveryMode(true);
      if (mounted) {
        setUser(session?.user ?? null);
        mergeOnSession(session?.user ?? null);
      }
    });
    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, [mergeOnSession]);

  const signUp = useCallback(async (email: string, password: string) => {
    setAuthError(null);
    setAuthNotice(null);
    // emailRedirectTo aims the confirmation link at the LIVE app —
    // without it Supabase falls back to the project's site URL,
    // which still points at a dev address (localhost:3000), so the
    // confirmation landed on a dead page (found 2026-11-14).
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { emailRedirectTo: appUrl() },
    });
    if (error) {
      setAuthError(error.message);
      return;
    }
    // Supabase's default requires email confirmation, so a fresh
    // sign-up usually comes back with no session. That is not an
    // error — the player confirms from their inbox, then signs in.
    if (!data.session) {
      setAuthNotice('Account created — check your email to confirm it, then sign in.');
    }
  }, []);

  const signIn = useCallback(async (email: string, password: string) => {
    setAuthError(null);
    setAuthNotice(null);
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) setAuthError(error.message);
  }, []);

  const signInWithGoogle = useCallback(async () => {
    setAuthError(null);
    setAuthNotice(null);
    // NOTE: the Google provider must be enabled in the Supabase
    // dashboard (Authentication > Providers > Google) or this returns
    // a clear provider error instead of redirecting.
    const { error } = await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: {
        redirectTo: `${window.location.origin}${process.env.REACT_APP_BASENAME || '/GLACER'}/profile`,
      },
    });
    if (error) setAuthError(error.message);
  }, []);

  const signOut = useCallback(async () => {
    setAuthError(null);
    setAuthNotice(null);
    const { error } = await supabase.auth.signOut();
    if (error) setAuthError(error.message);
  }, []);

  const resetPassword = useCallback(async (email: string) => {
    setAuthError(null);
    setAuthNotice(null);
    if (!email) {
      setAuthError('Enter your email above first — the reset link is sent to that inbox.');
      return;
    }
    // Same live-app redirect as sign-up: the reset email's link must
    // land back in this app (where the recovery form waits), not on
    // the project's stale dev site URL.
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: appUrl(),
    });
    if (error) {
      setAuthError(error.message);
      return;
    }
    setAuthNotice('Reset email sent — check your inbox and tap the link to set a new password.');
  }, []);

  const updatePassword = useCallback(async (password: string): Promise<string | null> => {
    const { error } = await supabase.auth.updateUser({ password });
    if (error) return error.message;
    // Success: the recovery session is now a normal signed-in
    // session. Strip the one-time auth params from the URL so a
    // refresh does not re-enter recovery mode. (The app does not
    // route on the hash, so clearing auth params is safe; a plain
    // in-page anchor like #account is left alone.)
    try {
      if (
        window.location.hash.includes('access_token') ||
        window.location.hash.includes('type=recovery')
      ) {
        window.history.replaceState(null, '', window.location.pathname + window.location.search);
      }
    } catch {
      // Non-fatal: the password is already changed either way.
    }
    return null;
  }, []);

  const dismissRecovery = useCallback(() => {
    setRecoveryMode(false);
  }, []);

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        authError,
        authNotice,
        signUp,
        signIn,
        signInWithGoogle,
        signOut,
        resetPassword,
        recoveryMode,
        updatePassword,
        dismissRecovery,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};
