// Icebreaker notice PRODUCER (Round 17, Eddie 2026-11-17) —
// headless. Replaces components/IcebreakerNotification.tsx, which
// rendered the icebreaker as a top-centre pill; Eddie's
// notifications brief replaced the pills with one system (store +
// corner toasts + a permanent home), so the pill renderer is gone
// and this producer writes each offer into the notifications store
// instead. The offer itself still lives in PresenceContext with
// its exact old lifecycle — suppression by status, per-day
// dismissals, one at a time. Only its ANNOUNCEMENT moved:
//
// - When an offer fires, one record is stored (per-day id — the
//   store dedupes, so the same person is never announced twice in
//   a day) and the corner toast pops.
// - The toast going down (auto-dismiss or ✕) no longer kills the
//   offer on a timer the way the pill did: the record in the
//   notifications home IS the persistent path to the person, and
//   tapping it (toast or home) opens their meet card through
//   PresenceContext.meetPerson — the old "Say hi", generalized.
// - The toast's ✕ still resolves the live offer (dismissIcebreaker)
//   — "not now" means not now, exactly as before.
//
// CONDUCT RULE (Eddie, 2026-11-13 — standing design law) is
// untouched: the copy below is the pill's own headline logic, and
// every line stays polite, warm, and professional.
import React, { useEffect, useRef } from 'react';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { useNotifications } from '../contexts/NotificationsContext';
import { usePresence } from '../contexts/PresenceContext';
import { localDateString } from '../utils/presence';

const IcebreakerNoticeProducer: React.FC = () => {
  const { icebreakerOffer } = usePresence();
  const { userNavitar } = useNavitarFightClub();
  const { notify } = useNotifications();
  // The offer instance already announced (person|venue). Reset
  // when the offer clears so a genuinely new offer announces again
  // (the store's per-day id still dedupes repeats within a day).
  const announcedKeyRef = useRef<string | null>(null);

  useEffect(() => {
    if (!icebreakerOffer) {
      announcedKeyRef.current = null;
      return;
    }
    if (!userNavitar) return;
    const { person, venue, reason, opener } = icebreakerOffer;
    const key = `${person.id}|${venue.id}`;
    if (announcedKeyRef.current === key) return;
    announcedKeyRef.current = key;

    // The pill's headline logic, unchanged: the strongest match
    // context names the card when there is one.
    const headline =
      reason?.kind === 'business'
        ? `${userNavitar.name} spotted a business match`
        : reason?.kind === 'interest'
          ? `${userNavitar.name} spotted a shared interest`
          : reason?.kind === 'dating'
            ? `${userNavitar.name} spotted a possible dating intro`
            : `${userNavitar.name} has an icebreaker for you`;
    notify({
      id: `icebreaker-${person.id}-${localDateString()}`,
      kind: 'icebreaker',
      title: headline,
      body: reason ? reason.detail : `${person.name} at ${venue.name} — “${opener}”`,
      route: '/map',
      venueId: venue.id,
      personId: person.id,
      demo: true,
    });
  }, [icebreakerOffer, userNavitar, notify]);

  return null;
};

export default IcebreakerNoticeProducer;
